      sources: [{ name: "Scooter Braun Sells Taylor Swift's Big Machine Masters for Big Payday", url: "https://variety.com/2020/music/news/scooter-braun-sells-taylor-swift-big-machine-masters-1234832080/" }, { name: "Taylor Swift Gets Her Masters Back: How We Got Here", url: "https://www.hollywoodreporter.com/music/music-news/taylor-swift-buys-back-her-catalog-explainer-1236233783/" }, { name: "Taylor Swift masters dispute", url: "https://en.wikipedia.org/wiki/Taylor_Swift_masters_dispute" }],
