      sources: [{ name: "Wikipedia", url: "https://en.wikipedia.org/wiki/Speak_Now_World_Tour" }, { name: "Billboard", url: "https://www.billboard.com/music/music-news/taylor-swift-announces-speak-now-world-tour-950374/" }],
